begin;
select plan(14);
select has_table('public','gamification_activity','live activity facts');
select has_table('public','quest_lifecycle','slot and baseline metadata');
select is((select relrowsecurity from pg_class where oid='public.gamification_activity'::regclass),true,'activity RLS');
select is((select relrowsecurity from pg_class where oid='public.quest_lifecycle'::regclass),true,'lifecycle RLS');
select ok(not has_table_privilege('anon','public.gamification_activity','SELECT'),'anonymous cannot read activity');
select ok(not has_table_privilege('authenticated','public.gamification_activity','UPDATE'),'client cannot rewrite live facts');
insert into public.gamification_activity values('00000000-0000-0000-0000-000000000071','progress:one','progress','00000000-0000-0000-0000-000000000072',1,'2026-10-05','2026-10-05T12:00:00Z');
select throws_ok($$update public.gamification_activity set quantity=2$$,'P0001',null,'live facts immutable');
insert into public.quest_instances(owner_id,id,template_key,cadence,period_key,title,unit,target,progress) values('00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000072','progress.record','daily','2026-10-05','Record','updates',1,0);
insert into public.quest_lifecycle values('00000000-0000-0000-0000-000000000071','00000000-0000-0000-0000-000000000072',0,0,now());
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000071',true);
select is((select count(*)::int from public.gamification_activity),1,'owner reads activity');
select is((select count(*)::int from public.quest_lifecycle),1,'owner reads slots');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000073',true);
select is((select count(*)::int from public.gamification_activity),0,'other owner cannot read activity');
select is((select count(*)::int from public.quest_lifecycle),0,'other owner cannot read slots');
select throws_ok($$insert into public.gamification_activity values('00000000-0000-0000-0000-000000000071','wrong-owner','progress','00000000-0000-0000-0000-000000000072',1,'2026-10-05',now())$$,'42501',null,'cross-owner insert rejected');
reset role;
select throws_ok($$insert into public.user_cosmetics values('00000000-0000-0000-0000-000000000071','invented','equipped',now())$$,'23514','Unknown or locked cosmetic','unknown catalog key rejected');
select throws_ok($$insert into public.user_cosmetics values('00000000-0000-0000-0000-000000000071','accent.berry','equipped',now())$$,'23514','Unknown or locked cosmetic','locked cosmetic rejected');
select * from finish(); rollback;
